\u0079\u0054\u0049\u0063\u0030\u0071\u0052\u0061\u0035\u002b\u002b\u007e\u007d\u004e\u002f\u0023\u0035\u004f\u0030\u0031\u0071\u002f\u0074\u0032\u0064\u0022\u006d\u0054\u005f\u0033\u0034\u0029\u002b\u003f\u004e\u0030\u0074\u0057\u002b\u0034\u0064\u004c\u004a\u0066\u0077\u002f\u0050\u007c\u0054\u007d\u0034\u0067\u0072\u0068\u0052\u007c\u006b\u002b\u0029\u0031\u003f\u0046\u002f\u0064\u0054\u0060\u0075\u0054\u0056\u0021\u0046\u005b\u0050\u005a\u0061\u0074\u0043\u002c\u0029\u0071\u0038\u004b\u0026\u0052\u0055\u002a\u002c\u0071\u005b\u0023\u0039\u0051\u004e\u0052\u0042\u0066\u004a\u002b\u0054\u0072\u0028\u0064\u0061\u0042\u003e\u0052\u0076\u0069\u0030\u0060\u003b\u002b\u0052\u0023\u0068\u003e\u005f\u0040\u006e\u003c\u007c\u0063\u0038\u0028\u0061\u0040\u0032\u0025\u0064\u002a\u003e\u0044\u006f\u0078\u004c\u003f\u0024\u004d\u007c\u0066\u0030\u004c\u0071\u0051\u0064\u0068\u0033\u0078\u006a\u003d\u0029\u0062\u0047\u007b\u0024\u0039\u007c\u0033\u0052\u0059\u004d\u007e\u0056\u004c\u007d\u0065\u005a\u0026\u002c\u0064\u0041\u004c\u0041\u0042\u0030\u003c\u002a\u0025\u0028\u0030\u0064\u004f\u0050\u0056\u004d\u0075\u0048\u006f\u0037\u0038\u0025\u002b\u0077\u0025\u0058\u0059\u0066\u0061\u002b\u004a\u0034\u0057\u0022\u0040\u0032\u0031\u0026\u0052\u0039\u0061\u006e\u0059\u007d\u0040\u0021\u0033\u007c\u0035\u002b\u0078\u0039\u0073\u0024\u0055\u0023\u0061\u0055\u0056\u006c\u0062\u0021\u0077\u0065\u002a\u0051\u0074\u007c\u0076\u004e\u0073\u0031\u005b\u0074\u0052\u0034\u0032\u0052\u005d\u005e\u0059\u0031\u0058\u003d\u004c\u0073\u005d\u0041\u004e\u007b\u005b\u005e\u003a\u005e\u003d\u0073\u0022\u0041\u0071\u0031\u0066\u006c\u0072\u007b\u003a\u0074\u0037\u0038\u0034\u0030\u0033\u0041\u0039\u0073\u0024\u0055\u0053\u002f\u0060\u0039\u0079\u0062\u006e\u0062\u005a\u0040\u0054\u0039\u004b\u0068\u0070\u003c\u002e\u006a\u0034\u0055\u004c\u007e\u0059\u0057\u0067\u0032\u002f\u0055\u007e\u007c\u0073\u005d\u0049\u0024\u0070\u006d\u0079\u0065\u0059\u003e\u0023\u0058\u0073\u0078\u0041\u0026\u003d\u0026\u0050\u003b\u0072\u0058\u0031\u0063\u0053\u002f\u003e\u003d\u0055\u003d\u0053\u0033\u004e\u004d\u0061\u0060\u0059\u006f\u003e\u0029\u0024\u0051\u0064\u004b\u0052\u0036\u0062\u002b\u0050\u0065\u0069\u006e\u002b\u0059\u0066\u0077\u0077\u0053\u004e\u005f\u0031\u0054\u0050\u0036\u0075\u006a\u0037\u0032\u0031\u0024\u0061\u0077\u006b\u0056\u0071\u0039\u0024\u003d\u003d\u0077\u0024\u006f\u0026\u0033\u0036\u0041\u0039\u0058\u005a\u006d\u0074\u002f\u0069\u0041\u005d\u0064\u004a\u005b\u0050\u0056\u0028\u0046\u0049\u0042\u004e\u004c\u0051\u0072\u006b\u002f\u006d\u0035\u0066\u0059\u0037\u0059\u0048\u0055\u0031\u0066\u002e\u002f\u003e\u0057\u0024\u0066\u0032\u0034\u0062\u003c\u0035\u0048\u0037\u004c\u002c\u003f\u0051\u002f\u0047\u003d\u0069\u002c\u0038\u0064\u0058\u0054\u0057\u0076\u0076\u0053\u0036\u0049\u0035\u003e\u0037\u0048\u006c\u0051\u0035\u006f\u0034\u0051\u0042\u0071\u0046\u0066\u0030\u0036\u004a\u0068\u006b\u0038\u0078\u0024\u0074\u006d\u0045\u0046\u0028\u0056\u005e\u0030\u005d\u0025\u0067\u006c\u0056\u0042\u0057\u0050\u0058\u006f\u005d\u0037\u0060\u0069\u003f\u0054\u0066\u007a\u0034\u006a\u0063\u0067\u002c\u0034\u0049\u0035\u003c\u0037\u003a\u0041\u0076\u0078\u0034\u0051\u0063\u005f\u003b\u0032\u0024\u0070\u002c\u0077\u0067\u007d\u0052\u004e\u0050\u0050\u0063\u006b\u0055\u0057\u0026\u0048\u0072\u0038\u0066\u0077\u0071\u0051\u0038\u0078\u0030\u0041\u002b\u006d\u0055\u0074\u0073\u004e\u0029\u0048\u002e\u004c\u002f\u0046\u0079\u007a\u0037\u006a\u0076\u0051\u0059\u005e\u0073\u0066\u006e\u0055\u0071\u003e\u002b\u002e\u002f\u004a\u005b\u004f\u006e\u0021\u0053\u0042\u0058\u004d\u0039\u004c\u004f\u003d\u004f\u004b\u0038\u004d\u005f\u0074\u003f\u0050\u0065\u0055\u0069\u0059\u002a\u003b\u006d\u0053\u0022\u0076\u0047\u0067\u0075\u0031\u0039\u0066\u003b\u005d\u0028\u004e\u0079\u006f\u0030\u0028\u006a\u0026\u006c\u0062\u003f\u006e\u003c\u002f\u006d\u0035\u0023\u0067\u0058\u002f\u007d\u0021\u0035\u005f\u002a\u002a\u0079\u0052\u0056\u0070\u0035\u0030\u0053\u0034\u0070\u0024\u0061\u0077\u006b\u0056\u0071\u0030\u0037\u004c\u0062\u006f\u004b\u0031\u0049\u0066\u002e\u0053\u0071\u005a\u0042\u0035\u003d\u0069\u0052\u0036\u0062\u002b\u0061\u004e\u005b\u007d\u0029\u002a\u0021\u0032\u0035\u0057\u0039\u0024\u003d\u005e\u0031\u005a\u007a\u0045\u0077\u0029\u0053\u0029\u0049\u006b\u0065\u0054\u0031\u007d\u0041\u0021\u006b\u006d\u0026\u0054\u0054\u0031\u0028\u006b\u003d\u0030\u0052\u002e\u0060\u0069\u005b\u003d\u0049\u007e\u0022\u0068\u0065\u004f\u0054\u0078\u0073\u0049\u0066\u002e\u003b\u006d\u0058\u0037\u0060\u002c\u0032\u0055\u0050\u0053\u003c\u0038\u003d\u0026\u003f\u0064\u0068\u0068\u003b\u0078\u002b\u0072\u0029\u0058\u0045\u006a\u006a\u007c\u004b\u0035\u0050\u004b\u007b\u0043\u007d\u0064\u0069\u0068\u0030\u006f\u006e\u0029\u0063\u004d\u0064\u0062\u0026\u004e\u003b\u0023\u0064\u0037\u0033\u0063\u003a\u0023\u005e\u0036\u0025\u0053\u006f\u007a\u003d\u0025\u0068\u0055\u0048\u005d\u0077\u007c\u002b\u002b\u0061\u0029\u003b\u003d\u006c\u0059\u0026\u0078\u0032\u0073\u0060\u004b\u0053\u0045\u0072\u0029\u0035\u0074\u0077\u0067\u0078\u0077\u006b\u0055\u006a\u0074\u0024\u0054\u0053\u0051\u003f\u003d\u0044\u0051\u0021\u0076\u006f\u0031\u0022\u0022\u0058\u0056\u007d\u0023\u002a\u0026\u006d\u0070\u0056\u0065\u004b\u0079\u004a\u003b\u0047\u0058\u0047\u0054\u0023\u0079\u0033\u0063\u0042\u002c\u003f\u003b\u0059\u0031\u006d\u006f\u006c\u0033\u0077\u0057\u0021\u0045\u0063\u0073\u0033\u002e\u0070\u0074\u0031\u0054\u007c\u0034\u004d\u002f\u0030\u006f\u006f\u0079\u0069\u0023\u0065\u0045\u0076\u006a\u007a\u0034\u0031\u0062\u0039\u0053\u002f\u0029\u0063\u006f\u0037\u0022\u005e\u002b\u0029\u0047\u006f\u002a\u003d\u005d\u002b\u0056\u0073\u0075\u0057\u004a\u0050\u002a\u0049\u004f\u0071\u005a\u0076\u0058\u0029\u0072\u0028\u0039\u0069\u0044\u006b\u003f\u0031\u0079\u0021\u0050\u0039\u0028\u0060\u003c\u0024\u0069\u006e\u006e\u0055\u0074\u0052\u007b\u003e\u0035\u002e\u0044\u004a\u0072\u0070\u004c\u0031\u006f\u0056\u0048\u0052\u007e\u0051\u0030\u004d\u0044\u0038\u003b\u0037\u004a\u0025\u0041\u0064\u0062\u0046\u003d\u002b\u0029\u0047\u0059\u0059\u0043\u003e\u006f\u0025\u0079\u0025\u0046\u0056\u0040\u0069\u0040\u004d\u0064\u0079\u0039\u005d\u0065\u0028\u0030\u002e\u0079\u005e\u0073\u0039\u0046\u0047\u0050\u0024\u006a\u006c\u007b\u003c\u004a\u007a\u0071\u0050\u002c\u005e\u004d\u0043\u005f\u0030\u0054\u005e\u0060\u003a\u0035\u0073\u006e\u0063\u0028\u002c\u005e\u006c\u0073\u0038\u0046\u0061\u0067\u0037\u0038\u002b\u003b\u0058\u0044\u004a\u004f\u0035\u0074\u002a\u0044\u005e\u0036\u0059\u003d\u0067\u002a\u0053\u0039\u0062\u003f\u0070\u0047\u0039\u005e\u006c\u0055\u0051\u0051\u0037\u005a\u005a\u004c\u0071\u005d\u007b\u0032\u007b\u003a\u0024\u0048\u0034\u0025\u0040\u004e\u003f\u0047\u0056\u005f\u003f\u003a\u0061\u0029\u0065\u0025\u0061\u0051\u002e\u0024\u004c\u0053\u0026\u0039\u0056\u0034\u0065\u0065\u003c\u003e\u0049\u003d\u0041\u0040\u002e\u0023\u0050\u0066\u006b\u0077\u005a\u007a\u007c\u0033\u0058\u007d\u0051\u003d\u002a\u0059\u0074\u0066\u0065\u002f\u0072\u003f\u005f\u0048\u0064\u0049\u0079\u002a\u006d\u007b\u0061\u0028\u007c\u003e\u0033\u0031\u0037\u0059\u0074\u006c\u006f\u0061\u0021\u0034\u0021\u003a\u0040\u0029\u0075\u005f\u004c\u0047\u0051\u0031\u0024\u0025\u002c\u0028\u0065\u0060\u0036\u0054\u005b\u0042\u0033\u0039\u0056\u003e\u005a\u0032\u005f\u003b\u004e\u007d\u0025\u0038\u005f\u006a\u0026\u0023\u0079\u0047\u003b\u004c\u0046\u0040\u0028\u0077\u004e\u007d\u006f\u0071\u0036\u005a\u0046\u002f\u0046\u006d\u0034\u0077\u0065\u0053\u006d\u0026\u0075\u0036\u0022\u0037\u007c\u006c\u0040\u004b\u005f\u004c\u005a\u0072\u0058\u0056\u0033\u0057\u0062\u004c\u007e\u003d\u0030\u0068\u0076\u0065\u0055\u002c\u002f\u007b\u003f\u0044\u0039\u006b\u0062\u0026\u0065\u0031\u0054\u002f\u002f\u003e\u0072\u0058\u0052\u0037\u0039\u0071\u0051\u0029\u0071\u0072\u0075\u0044\u003d\u0049\u0049\u0054\u003d\u0057\u0052\u003d\u0033\u002c\u0036\u004b\u0034\u0047\u004d\u0034\u003c\u0043\u0058\u004c\u002f\u002b\u0069\u0072\u006f\u0049\u003b\u004c\u004d\u0043\u0054\u0039\u0044\u0062\u0059\u0056\u0043\u0065\u0024\u0061\u006d\u0059\u002b\u0053\u006e\u0059\u0029\u0049\u0047\u0079\u003d\u006e\u002e\u0044\u0039\u006c\u0055\u002b\u0070\u0031\u0072\u002e\u0029\u0034\u0079\u002e\u0031\u002c\u0040\u0054\u0061\u0066\u002e\u0034\u0058\u002e\u0024\u0056\u007e\u0039\u0075\u0070\u0046\u0072\u006e\u002c\u0077\u0059\u004f\u004f\u0058\u0069\u005e\u0048\u004d\u003f\u0074\u006f\u0044\u0052\u0077\u0026\u0031\u0058\u003f\u002b\u005f\u0071\u003c\u0059\u0066\u0030\u005f\u002c\u002c\u0077\u0059\u004f\u004f\u0058\u003e\u006a\u0057\u006d\u0071\u0030\u0055\u0042\u0041\u0034\u0030\u0062\u0057\u003a\u004f\u0067\u003e\u0070\u004b\u0045\u007c\u006d\u005f\u0043\u0060\u0067\u006d\u0031\u003e\u0055\u002b\u0072\u004b\u0031\u006f\u0043\u005f\u0024\u007b\u0029\u0049\u004c\u002f\u006c\u0051\u0035\u0052\u0073\u0028\u006f\u002a\u0057\u0063\u0043\u0031\u0063\u0053\u003e\u0033\u005e\u0037\u007e\u0036\u005e\u0062\u0079\u007e\u0065\u0065\u003c\u003a\u0038\u0023\u0047\u0079\u0076\u0043\u0079\u0022\u006a\u0063\u0030\u0063\u007c\u0071\u002a\u0024\u0055\u0054\u005f\u004c\u004c\u0071\u0038\u004e\u0066\u004c\u002c\u006e\u0062\u0021\u006c\u0077\u0037\u003a\u006e\u006e\u003f\u0033\u004b\u0075\u0048\u002b\u004a\u0040\u002a\u003a\u007c\u0052\u005f\u0031\u0052\u0065\u0033\u0031\u0039\u0038\u0052\u0030\u0061\u0036\u006b\u002b\u004a\u002c\u0078\u0045\u006f\u0067\u0070\u005b\u0022\u002b\u004a\u0048\u0038\u0043\u007c\u003e\u0035\u004b\u006d\u003e\u007a\u0058\u0075\u0057\u006c\u004a\u006a\u0056\u0039\u007c\u0025\u0055\u0036\u0049\u005a\u0040\u0049\u003f\u0076\u005e\u0028\u0060\u0032\u0063\u002e\u0077\u0050\u0035\u0050\u0025\u007e\u007a\u0068\u0069\u0073\u0076\u0064\u002c\u0065\u0026\u006f\u007a\u0038\u006c\u003a\u0065\u0037\u0054\u003c\u005f\u0073\u0021\u0040\u007a\u0068\u0069\u0073\u0076\u0064\u002e\u007d\u002b\u006e\u0075\u0051\u0055\u0064\u0056\u0064\u0064\u0047\u0056\u007e\u0047\u0033\u0049\u0055\u0035\u003f\u0054\u002f\u0036\u006d\u0025\u0056\u004d\u004d\u003c\u003b\u0049\u0065\u0064\u006e\u005f\u0052\u0064\u007e\u0044\u0033\u0036\u0041\u0077\u005a\u0041\u0034\u006a\u005f\u003c\u004b\u0039\u004c\u004b\u007e\u0030\u0063\u002e\u0058\u0023\u0057\u006c\u006a\u005d\u0050\u0030\u0076\u0026\u004e\u004d\u0042\u0041\u0033\u0038\u0021\u0065\u007b\u005b\u0046\u0030\u0041\u0024\u005d\u0070\u0065\u005a\u004c\u004d\u0054\u0061\u0066\u002e\u0034\u0058\u0028\u0037\u003d\u0033\u007e\u0058\u003d\u0051\u0056\u0071\u0072\u0026\u0035\u0079\u004a\u004d\u0061\u003d\u0051\u007c\u0033\u0072\u0078\u0042\u0028\u002f\u0061\u006d\u0059\u004d\u002a\u0040\u0060\u0078\u004c\u0061\u0062\u0059\u006c\u0048\u002b\u0063\u0079\u0033\u0038\u0026\u006e\u004a\u007c\u0078\u005b\u0072\u0062\u0063\u0022\u0077\u005d\u005d\u0060\u0054\u002c\u0067\u002e\u004a\u0023\u0042\u005f\u0024\u002e\u0069\u0022\u0059\u0023\u0062\u004b\u006e\u002c\u003c\u0038\u002a\u002c\u006a\u004d\u0076\u0059\u0075\u0061\u0041\u0026\u006d\u0073\u0065\u0079\u0046\u0026\u004d\u0021\u0058\u005f\u0060\u0066\u003d\u0074\u006f\u0056\u005f\u006a\u003b\u007b\u003e\u0077\u006f\u0058\u0035\u0030\u0043\u002e\u007e\u0042\u0035\u0026\u003b\u0060\u0034\u002e\u0072\u006e\u0041\u006e\u0074\u0030\u0025\u007e\u0037\u0062\u0024\u0021\u004a\u0046\u006f\u0057\u006d\u003a\u0031\u0056\u005d\u0039\u0029\u0051\u003b\u004d\u003c\u0039\u0038\u003e\u007e\u0075\u007e\u007e\u0043\u0041\u0029\u007d\u006e\u004d\u004f\u005d\u0070\u0054\u0034\u0052\u0041\u0028\u007e\u0030\u0023\u0073\u004f\u003d\u0076\u007a\u0040\u0042\u002e\u0065\u007d\u0076\u0062\u0024\u0056\u0066\u003e\u0045\u0041\u0061\u0030\u0070\u0063\u005a\u0056\u0078\u0058\u0046\u0039\u002c\u0072\u007e\u0067\u005f\u004d\u0028\u003f\u007e\u0026\u0042\u0054\u0055\u002f\u0057\u0029\u0050\u0057\u0042\u0063\u0042\u0028\u0062\u0026\u0062\u0061\u005b\u005b\u0079\u0061\u0032\u0061\u005a\u004d\u0064\u0024\u0035\u004d\u003b\u006a\u0023\u003e\u007c\u0068\u0036\u0068\u006b\u0058\u006a\u0028\u0055\u002f\u0071\u006b\u0045\u006e\u004a\u004f\u005e\u004d\u006a\u0021\u003b\u006b\u0048\u004a\u0078\u0032\u0053\u0039\u0041\u0036